html:
{% set bir_company = frappe.get_doc('Company', doc.company) %}
<div class="bir-wt-summary-print">
    <style>
        .bir-wt-summary-print {
            font-family: "Segoe UI", Arial, sans-serif;
            color: #000;
            background-color: #fff;
            padding: 5px;
        }
        .bir-header-sap {
            margin-bottom: 12px;
            border-bottom: 2px solid #000;
            padding-bottom: 8px;
        }
        .bir-header-sap h2 {
            text-align: center;
            font-weight: bold;
            text-transform: uppercase;
            margin-top: 0;
            margin-bottom: 10px;
            font-size: 16px;
            letter-spacing: 0.5px;
        }
        .sap-metadata-table {
            width: 100%;
            border-collapse: collapse;
            font-size: 9.5px;
            line-height: 1.3;
        }
        .sap-metadata-table td {
            padding: 2px 4px !important;
            border: none !important;
        }
        .sap-metadata-table td.label-cell {
            font-weight: bold;
            width: 12%;
            text-align: left;
        }
        .sap-metadata-table td.value-cell {
            width: 38%;
            text-align: left;
        }
        .bir-period {
            font-size: 11px;
            font-weight: bold;
            margin-top: 5px;
            margin-bottom: 8px;
            text-transform: uppercase;
        }
        .bir-table {
            width: 100%;
            border-collapse: collapse;
            font-size: 9.5px;
            border: 1px solid #000;
        }
        .bir-table th, .bir-table td {
            border: 1px solid #000;
            padding: 5px 6px;
            text-align: left;
            white-space: nowrap;
        }
        .bir-table th {
            background-color: #fff;
            font-weight: bold;
            text-transform: uppercase;
        }
        .bir-table td.num-cell {
            text-align: right;
        }
        .bir-table tr.total-row td {
            font-weight: bold;
        }
        @media print {
            @page {
                size: landscape;
                margin: 6mm 4mm 4mm 4mm;
            }
            .bir-wt-summary-print {
                width: 100%;
            }
            .bir-table {
                font-size: 7.5px;
            }
            .sap-metadata-table {
                font-size: 8.5px;
            }
        }
    </style>

    <div class="bir-header-sap">
        <h2>Withholding Summary Report</h2>
        <table class="sap-metadata-table">
            <tr>
                <td class="label-cell">Company:</td>
                <td class="value-cell">{{ bir_company.company_name or doc.company }}</td>
                <td class="label-cell">Line of Business:</td>
                <td class="value-cell">{{ doc.line_of_business or '' }}</td>
            </tr>
            <tr>
                <td class="label-cell">Address:</td>
                <td class="value-cell">{{ doc.address_display or '' }}</td>
                <td class="label-cell">Zip:</td>
                <td class="value-cell">{{ doc.zip or '' }}</td>
            </tr>
            <tr>
                <td class="label-cell">TIN:</td>
                <td class="value-cell">{{ bir_company.tax_id or '' }}</td>
                <td class="label-cell">Email:</td>
                <td class="value-cell">{{ doc.email or '' }}</td>
            </tr>
            <tr>
                <td class="label-cell">RDO:</td>
                <td class="value-cell">{{ doc.rdo or '' }}</td>
                <td class="label-cell">Mobile / Tel:</td>
                <td class="value-cell">
                    {{ doc.mobile or '' }}{% if doc.telephone %} / {{ doc.telephone }}{% endif %}
                </td>
            </tr>
        </table>
    </div>

    <div class="bir-period">
        Period: {{ frappe.format(doc.from_date, {fieldtype: 'Date'}) if doc.from_date else '' }} to {{ frappe.format(doc.to_date, {fieldtype: 'Date'}) if doc.to_date else '' }}
    </div>

    <div style="overflow-x: auto; -webkit-overflow-scrolling: touch; width: 100%; margin-bottom: 20px;">
        <table class="bir-table">
            <thead>
                <tr>
                    <th>Document</th>
                    <th>Doc Date</th>
                    <th>Tax Date</th>
                    <th>Doc No.</th>
                    <th>BP Code</th>
                    <th>BP Name</th>
                    <th>TIN</th>
                    <th>WT Code</th>
                    <th style="text-align: right;">WT Rate</th>
                    <th style="text-align: right;">WT Taxable</th>
                    <th style="text-align: right;">WT Amount</th>
                    <th>Status</th>
                </tr>
            </thead>
            <tbody>
                {% set totals = {'taxable': 0.0, 'amount': 0.0} %}
                {% for row in doc.withholding_entries %}
                    <tr>
                        <td>{{ row.document_type or '' }}</td>
                        <td style="white-space: nowrap;">{{ frappe.format(row.doc_date, {fieldtype: 'Date'}) if row.doc_date else '' }}</td>
                        <td style="white-space: nowrap;">{{ frappe.format(row.tax_date, {fieldtype: 'Date'}) if row.tax_date else '' }}</td>
                        <td>{{ row.doc_no or '' }}</td>
                        <td>{{ row.bp_code or '' }}</td>
                        <td>{{ row.bp_name or '' }}</td>
                        <td>{{ row.tin or '' }}</td>
                        <td style="text-align: center;">{{ row.wt_code or '' }}</td>
                        <td class="num-cell">{{ "{:,.2f}".format(row.wt_rate or 0) }}</td>
                        <td class="num-cell">{{ "{:,.2f}".format(row.wt_taxable or 0) }}</td>
                        <td class="num-cell">{{ "{:,.2f}".format(row.wt_amount or 0) }}</td>
                        <td style="font-weight: bold; text-align: center; color: #000;">{{ row.status or '' }}</td>
                    </tr>
                    {% if totals.update({
                        'taxable': totals.taxable + (row.wt_taxable or 0),
                        'amount': totals.amount + (row.wt_amount or 0)
                    }) %}{% endif %}
                {% endfor %}
                <tr class="total-row">
                    <td colspan="9">TOTAL</td>
                    <td class="num-cell">{{ "{:,.2f}".format(totals.taxable) }}</td>
                    <td class="num-cell">{{ "{:,.2f}".format(totals.amount) }}</td>
                    <td></td>
                </tr>
            </tbody>
        </table>
    </div>
</div><style>
        .bir-table { width:100%; table-layout:fixed; }
        .bir-table th, .bir-table td { white-space:normal !important; overflow-wrap:anywhere; word-wrap:break-word; padding:3px 2px; }
        .bir-table thead { display:table-header-group; }
        .bir-table tr { page-break-inside:avoid; }
        @media print { .bir-table { font-size:7.5px; } }
        </style>
